                choices.append((axis, i, vals[0]))
    if not choices:
        return [r[:] for r in grid]
    # Select orientation with the most regularly spaced divider lines.
    scored = []
    for axis in (0, 1):
        inds = sorted(i for a, i, _ in choices if a == axis)
        if len(inds) >= 1:
            diffs = [b-a for a,b in zip(inds, inds[1:])]
            period = min(diffs) if diffs else None
            scored.append((len(inds), axis, inds, period))
    _, axis, inds, period = max(scored, key=lambda x: (x[0], -x[1]))
    n = h if axis == 0 else w
    if period is None:
        # A single divider splits the grid into two equal bands in these tasks.
        period = min(inds[0], n-inds[0]-1)
    if period <= 0:
        return [r[:] for r in grid]
    # Divider rows/columns occur at period-1 modulo period.
    starts = list(range(0, n, period + 1))
    bands = []
    for s in starts:
        e = min(s + period, n)
        if e > s:
            bands.append((s,e))
    def get_band(s,e):
        if axis == 0:
            return [row[:] for row in grid[s:e]]
        return [[grid[r][c] for c in range(s,e)] for r in range(h)]
    def score_band(b):
        return sum(v != bg for row in b for v in row)
    src = max(bands, key=lambda se: score_band(get_band(*se)))
    templ = get_band(*src)
    out = [r[:] for r in grid]
    for s,e in bands:
        if (s,e) == src:
            continue
        for k in range(e-s):
            if axis == 0:
                out[s+k] = templ[k][:]
            else:
                for r in range(h):
                    out[r][s+k] = templ[r][k]
    return out
